import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class Patch implements Opcodes{
 static int hooks;static final String H="dev/zomboid/hordes/CorpseBalance35",B="dev/zomboid/remains/CorpseBridge35";
 static MethodInsnNode call(String o,String n,String d){return new MethodInsnNode(INVOKESTATIC,o,n,d,false);}static void check(int n,int want,String text){if(n!=want)throw new IllegalStateException(text+" "+n);hooks++;System.out.println(text);}
 static byte[]patch(byte[]bytes,String kind)throws Exception{ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
 if(kind.equals("hordes")){
 if(c.name.equals("dev/zomboid/hordes/ScarcityControls")&&(m.name.equals("install")||m.name.equals("prepare"))){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));if(m.name.equals("install"))x.add(new VarInsnNode(ALOAD,3));x.add(call(H,m.name.equals("install")?"defaults":"prepare",m.name.equals("install")?"(Ljava/util/Map;Ljava/util/Map;)V":"(Ljava/util/Map;)V"));m.instructions.insertBefore(a,x);n++;}check(n,1,"single corpse probabilities "+m.name);}
 if(c.name.equals("dev/zomboid/hordes/WorldTuning")&&m.name.equals("load")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){m.instructions.insertBefore(a,call(H,"migrate","()V"));n++;}check(n,2,"one-time targeted rate migration");}
 }
 if(kind.equals("remains")){
 if(c.name.equals("dev/zomboid/remains/ZombieRemainsLoot")){int n=0,clears=0;for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc){if(mc.owner.equals("dev/zomboid/remains/ScarcityCompat33")&&mc.name.equals("body")){mc.owner=B;n++;}if(mc.name.equals("clear")&&mc.owner.equals("java/util/Collection")&&m.desc.contains("LivingDropsEvent")){m.instructions.insertBefore(a,new VarInsnNode(ALOAD,0));mc.setOpcode(INVOKESTATIC);mc.owner=B;mc.name="clear";mc.desc="(Ljava/util/Collection;Ljava/lang/Object;)V";mc.itf=false;clears++;}}if(n>0){check(n,1,"final normal corpse routing");check(clears,1,"preserve event drops before native clear");}}
 if(c.name.equals("dev/zomboid/remains/delivery/NpcCorpses")&&m.name.equals("place")){int n=0;for(AbstractInsnNode a:m.instructions.toArray())if(a instanceof MethodInsnNode mc&&mc.owner.equals("java/util/Map")&&mc.name.equals("put")){InsnList x=new InsnList();x.add(new InsnNode(DUP));x.add(new VarInsnNode(ALOAD,1));x.add(call(B,"scatter","(Ljava/lang/Object;Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);n++;}check(n,1,"scatter NPC inventory after decode and before placement");}
 if(c.name.equals("dev/zomboid/remains/delivery/NpcCorpses")&&m.name.equals("death")){int n=0;for(AbstractInsnNode a:m.instructions)if(a instanceof MethodInsnNode mc&&mc.owner.equals("dev/zomboid/remains/ProfileCompat")&&mc.name.equals("corpse")){mc.owner=B;mc.name="body";n++;}check(n,1,"NPC cargo, military bandages and scatter before encode");}
 }
 }
 if(hooks==before)return bytes;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 static byte[]events(){ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC|ACC_FINAL,"dev/zomboid/remains/EquipmentCapture35",null,"java/lang/Object",null);AnnotationVisitor a=w.visitAnnotation("Lnet/neoforged/fml/common/EventBusSubscriber;",true);a.visit("modid","zombie_remains_loot");a.visitEnd();MethodVisitor m=w.visitMethod(ACC_PUBLIC|ACC_STATIC,"death","(Lnet/neoforged/neoforge/event/entity/living/LivingDeathEvent;)V",null,null);m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESTATIC,B,"capture","(Ljava/lang/Object;)V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();w.visitEnd();return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]>r=new TreeMap<>();try(ZipFile z=new ZipFile(a[1])){for(ZipEntry e:Collections.list(z.entries())){byte[]bytes=z.getInputStream(e).readAllBytes();r.put(e.getName(),e.getName().endsWith(".class")?patch(bytes,a[0]):bytes);}}String prefix=a[0].equals("hordes")?"dev/zomboid/hordes/":"dev/zomboid/remains/";try(var files=Files.walk(Path.of(a[3]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList()){String n=Path.of(a[3]).relativize(p).toString();if(n.startsWith(prefix))r.put(n,Files.readAllBytes(p));}}if(a[0].equals("remains"))r.put("dev/zomboid/remains/EquipmentCapture35.class",events());if(hooks!= (a[0].equals("hordes")?3:4))throw new IllegalStateException("hook total "+hooks);try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[2])))){for(var e:r.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}}
}
